const path = require('path');
const fs = require('fs');

const PACKAGE_DIR = path.join(__dirname, '..');
const OPCODE_DIR = path.join(require('os').homedir(), '.opencode');
const AGENTS_DIR = path.join(OPCODE_DIR, 'agents');

/**
 * Get list of available agents
 */
function getAgents() {
  const agentsDir = path.join(PACKAGE_DIR, 'agents');
  return fs.readdirSync(agentsDir)
    .filter(f => f.endsWith('.json'))
    .map(f => JSON.parse(fs.readFileSync(path.join(agentsDir, f), 'utf8')));
}

/**
 * Get list of available skills
 */
function getSkills() {
  const skillsDir = path.join(PACKAGE_DIR, 'skills');
  return fs.readdirSync(skillsDir)
    .filter(f => fs.statSync(path.join(skillsDir, f)).isDirectory())
    .map(name => ({
      name,
      path: path.join(skillsDir, name, 'SKILL.md')
    }));
}

/**
 * Get version
 */
function getVersion() {
  const pkg = JSON.parse(
    fs.readFileSync(path.join(PACKAGE_DIR, 'package.json'), 'utf8')
  );
  return pkg.version;
}

module.exports = {
  PACKAGE_DIR,
  OPCODE_DIR,
  AGENTS_DIR,
  getAgents,
  getSkills,
  getVersion
};

